"""Bake illustrative coastal scenery with a physical water plane in Blender.
CC0 Fish Hoek Beach by Greg Zaal/Poly Haven supplies the sky and distant coast.
The near beach is occluded by a shaded water surface. This is not a reconstruction
of the reference anchorage. Native illumination uses linear HDR; the background
JPEG uses Three.js's MIT-licensed Neutral tone curve for consistent display.
"""
import bpy,numpy as np,json,hashlib,math
from pathlib import Path
R=Path(__file__).resolve().parents[1];O=R/'public/assets/saloon';O.mkdir(parents=True,exist_ok=True)
bpy.ops.wm.read_factory_settings(use_empty=True);s=bpy.context.scene;s.render.engine='CYCLES';s.cycles.device='CPU';s.cycles.samples=64;s.cycles.max_bounces=4;s.cycles.diffuse_bounces=2;s.cycles.use_denoising=False;s.render.threads_mode='FIXED';s.render.threads=5
world=bpy.data.worlds.new('CC0 coastal sky');world.use_nodes=True;s.world=world;env=world.node_tree.nodes.new('ShaderNodeTexEnvironment');env.image=bpy.data.images.load(str(R/'work/material-sources/fish_hoek_beach_4k.hdr'));world.node_tree.links.new(env.outputs[0],world.node_tree.nodes['Background'].inputs[0]);world.node_tree.nodes['Background'].inputs[1].default_value=1
bpy.ops.mesh.primitive_plane_add(size=1000000);water=bpy.context.object;water.name='Illustrative water surface';m=bpy.data.materials.new('Opaque deep water surface');m.use_nodes=True;water.data.materials.append(m);nodes=m.node_tree.nodes;links=m.node_tree.links;p=nodes['Principled BSDF'];p.inputs['Base Color'].default_value=(.012,.028,.045,1);p.inputs['Roughness'].default_value=.16;p.inputs['IOR'].default_value=1.333
geometry=nodes.new('ShaderNodeNewGeometry');vector=nodes.new('ShaderNodeVectorMath');vector.operation='MULTIPLY';vector.inputs[1].default_value=(.65,3.7,.65);links.new(geometry.outputs['Position'],vector.inputs[0]);noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=1;noise.inputs['Detail'].default_value=3;noise.inputs['Roughness'].default_value=.65;links.new(vector.outputs[0],noise.inputs['Vector']);bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.45;bump.inputs['Distance'].default_value=.07;links.new(noise.outputs['Fac'],bump.inputs['Height']);fine=nodes.new('ShaderNodeTexNoise');fine.inputs['Scale'].default_value=17;fine.inputs['Detail'].default_value=2;links.new(vector.outputs[0],fine.inputs['Vector']);small=nodes.new('ShaderNodeBump');small.inputs['Strength'].default_value=.3;small.inputs['Distance'].default_value=.005;links.new(fine.outputs['Fac'],small.inputs['Height']);links.new(bump.outputs[0],small.inputs['Normal']);links.new(small.outputs[0],p.inputs['Normal'])
data=bpy.data.cameras.new('Exterior panorama');cam=bpy.data.objects.new('Exterior panorama',data);s.collection.objects.link(cam);s.camera=cam;data.type='PANO';data.panorama_type='EQUIRECTANGULAR';data.clip_end=2000000;cam.location=(0,0,5);cam.rotation_euler=(math.pi/2,0,0);s.render.resolution_x=4096;s.render.resolution_y=2048;s.render.resolution_percentage=100;s.render.image_settings.file_format='OPEN_EXR';s.render.image_settings.color_mode='RGB';s.render.image_settings.color_depth='16';s.render.image_settings.exr_codec='PIZ';hdr=R/'work/material-sources/marine-environment-4k.exr';s.render.filepath=str(hdr);bpy.ops.render.render(write_still=True)
im=bpy.data.images.load(str(hdr));w,h=im.size;rgba=np.array(im.pixels[:],dtype=np.float32).reshape(h,w,4);rgb=np.maximum(0,rgba[:,:,:3]);linear=bpy.data.images.new('Coastal ambient HDR',w,h,float_buffer=True);linear.pixels.foreach_set(rgba.ravel());linear.update();linear.scale(2048,1024);linear.save_render(str(R/'work/material-sources/marine-ambient.exr'),scene=s)
minimum=np.min(rgb,axis=-1);offset=np.where(minimum<.08,minimum-6.25*minimum*minimum,.04);color=np.maximum(0,rgb-offset[...,None]);peak=np.max(color,axis=-1);new_peak=1-.24*.24/np.maximum(peak+.24-.76,1e-6);compressed=color*(new_peak/np.maximum(peak,1e-6))[...,None];g=1-1/(.15*(peak-new_peak)+1);compressed=compressed*(1-g[...,None])+new_peak[...,None]*g[...,None];color=np.where((peak<.76)[...,None],color,compressed);rgba[:,:,:3]=np.clip(color,0,1)
ldr=bpy.data.images.new('Neutral coastal background',w,h,float_buffer=True);ldr.pixels.foreach_set(rgba.ravel());ldr.update();s.view_settings.view_transform='Standard';s.view_settings.look='None';s.render.image_settings.file_format='JPEG';s.render.image_settings.color_depth='8';s.render.image_settings.quality=92;ldr.save_render(str(O/'exterior.jpg'),scene=s)
record={'source':json.loads((R/'work/material-sources/exterior-source.json').read_text()),'adaptation':'Sky and distant coast from CC0 HDRI, near beach occluded by a physical Blender water plane; illustrative scenery, not the yacht anchorage.','linearHDR':{'file':'marine-ambient.exr','sha256':hashlib.sha256((R/'work/material-sources/marine-ambient.exr').read_bytes()).hexdigest()},'displayJPEG':{'file':'exterior.jpg','width':w,'height':h,'sha256':hashlib.sha256((O/'exterior.jpg').read_bytes()).hexdigest()},'toneCurve':'Three.js 0.180.0 Neutral (MIT)'};(O/'exterior-source.json').write_text(json.dumps(record,indent=2)+'\n');bpy.ops.wm.save_as_mainfile(filepath=str(R/'work/marine-environment.blend'),compress=True);print('Prepared physically rendered coastal environment',flush=True)
